  ..._modules: Modules
): TaxKitClient<Modules> => ({
  calculations: {
    calculate: (calculation, input) => calculate(calculation, input),
    safe: {
      calculate: (calculation, input) => calculateSafe(calculation, input),
    },
  },
});

